const messages: Record<LanguageCode, Dictionary> = { en, th, ru, zh, ja, es, hi, fr }

export const translate = (language: LanguageCode, key: MessageKey, variables: Record<string, string | number> = {}) => {
  let value = messages[language][key] ?? en[key]
  Object.entries(variables).forEach(([name, replacement]) => { value = value.replaceAll(`{${name}}`, String(replacement)) })
  return value
}
